-- Standard v2 draft; local review artifact only. Not a numbered migration.
UPDATE lessons SET title='Rounding numbers: which landmark is nearer?', data=json_patch(data,'{"child_mission":"Use distances on a number line to round numbers to a ten or a hundred, and explain a midpoint decision.","coming_soon":null,"duration_minutes":60,"evidence_instructions":"Save the four labelled independent solutions and the two written quiz responses. A parent can note whether the learner compared both distances and named a midpoint tie. Paper and a typed summary are sufficient; no upload subscription is needed.","explicit_teaching":null,"extension":"Find a new number that rounds to different values at the nearest ten and hundred. Draw both scales and explain the distances. Then find an original number for which rounding through a ten would change the direct hundred answer.","follow_up_challenges":null,"guided_practice":"WE DO: Round 314 to the nearest ten. Write the endpoints and both distances before continuing.\nCompare after trying: 310 and 320; distances 4 and 6. Choose 310 because its distance is smaller. If you chose 320, draw ten equally spaced units and locate 314 before the midpoint.\n\nNow round 850 to the nearest hundred. Name the tie before choosing.\nCompare after trying: 800 and 900; distances 50 and 50. Neither is closer. Use the upward tie rule to select 900. If you said 900 was closer, correct the reason to equal distances and the agreed rule.","hoard_words":null,"independent_task":"YOU DO: Spend about 20 minutes on these new inputs.\n1. Round 163 to the nearest ten. Give both endpoints, both distances and a reason.\n2. Round 748 to the nearest hundred. Give both endpoints, both distances and a reason.\n3. Round 650 to the nearest hundred. Explain the midpoint decision without claiming that one endpoint is closer.\n4. Round 927 separately to the nearest ten and the nearest hundred. Start from 927 each time. Explain why the requested place changes the landmarks.\nThese are made-up numbers for practice, not measurements. Type your reasoning or draw number lines on paper and type a summary. Do not copy a teaching example. Keep your original attempts so a parent can see how you decided.","interactive_activities":null,"learning_area":"Mathematics","learning_intention":"We are learning to choose the nearest multiple of ten or hundred using endpoints, distances and midpoints.","lesson_number":1,"lesson_role":"Concept","materials":["Paper and pencil or the typed answer boxes","Optional: ruler for a number line"],"offline_alternative":"Copy the four independent prompts onto paper. Draw equally spaced number lines, circle both endpoints and label the distances. Keep the page and later type a short summary into the answer boxes. Read the printed teaching first if the method is unfamiliar.","outcome_codes":["MA2-RN-01"],"parent_notes":"Parent: Independent key: 163 uses 160 and 170, distances 3 and 7, so 160. 748 uses 700 and 800, distances 48 and 52, so 700. 650 uses 600 and 700, each 50 away, and rounds to 700 by the upward midpoint convention. 927 rounds to 930 with distances 7 and 3; to a hundred it rounds to 900 with distances 27 and 73. Look for reasons and scale labels, not just final values. Each solution is assessable separately.\n\nParent: Written model 1: To a ten: 450 and 460 are 6 and 4 away, so I choose 460. To a hundred: 400 and 500 are 56 and 44 away, so I choose 500. Each decision starts with 456.\n\nParent: Written model 2: 750 is 50 from both 700 and 800, so neither is nearer. It rounds to 800 because we use the agreed upward rule at an exact midpoint.\n\nParent: Keep the typed answers or the paper lines with a short typed summary. Accept spoken explanation recorded as a parent observation if writing is a barrier. The quiz score alone cannot show independent rounding reasoning. Outcome alignment is proposed and awaits NESA review; do not describe this draft as curriculum certified.","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":1,"explanation":"Rounding provides an approximate value at a stated place. It does not change the actual quantity, and situations needing exact counts still need the original value.","options":["Replacing an exact count in every situation","Giving an approximate value at a requested place","Changing the quantity of objects","Removing all digits"],"question":"What is rounding useful for?","type":"multiple_choice"},{"correct_index":2,"explanation":"590 and 600 are consecutive multiples of ten with 596 between them. Hundred landmarks or an interval covering two tens use the wrong scale.","options":["500 and 600","580 and 600","590 and 600","596 and 606"],"question":"Which neighbouring tens surround 596?","type":"multiple_choice"},{"correct_index":0,"explanation":"482 is 2 from 480 and 8 from 490. Choosing the endpoint with the smaller distance gives 480; keeping 482 would not be rounding to a ten.","options":["480","490","482","500"],"question":"Round 482 to the nearest ten.","type":"multiple_choice"},{"correct_index":3,"explanation":"619 lies between 610 and 620. It is 9 from the lower ten and only 1 from the upper ten, so it rounds to 620.","options":["600","610","619","620"],"question":"Round 619 to the nearest ten.","type":"multiple_choice"},{"correct_index":2,"explanation":"375 is exactly 5 from both 370 and 380. Neither is nearer, so the agreed upward midpoint rule selects 380.","options":["370","375","380","400"],"question":"Round 375 to the nearest ten using our midpoint rule.","type":"multiple_choice"},{"correct_index":1,"explanation":"800 and 900 are consecutive multiples of one hundred with 862 between them. The tens interval is the wrong scale and the other choices are not neighbouring hundreds.","options":["860 and 870","800 and 900","700 and 900","862 and 962"],"question":"Which neighbouring hundreds surround 862?","type":"multiple_choice"},{"correct_index":0,"explanation":"641 is 41 from 600 and 59 from 700. The lower hundred is closer. The values 640 and 650 are not the neighbouring hundreds.","options":["600","640","650","700"],"question":"Round 641 to the nearest hundred.","type":"multiple_choice"},{"correct_index":3,"explanation":"Direct comparison uses distances 49 and 51, so 249 rounds to 200. Rounding through 250 would introduce a midpoint tie and incorrectly select 300.","options":["Round to a ten and then round that answer","Always choose the upper hundred","Keep the first digit without considering distance","Compare the original 249 directly with 200 and 300"],"question":"Which approach avoids double rounding when finding the nearest hundred to 249?","type":"multiple_choice"},{"explanation":"The requested place determines the endpoints. Comparing distances from the original number provides a reason for each answer, rather than relying on an unexplained digit rule.","marking_guide":"Require both correct endpoints, distances and choices. Accept an accurate labelled line instead of subtraction sentences. Reject rounding the first answer instead of the original number.","question":"Round 456 separately to the nearest ten and the nearest hundred. Explain both choices.","sample_answer":"To a ten: 450 and 460 are 6 and 4 away, so I choose 460. To a hundred: 400 and 500 are 56 and 44 away, so I choose 500. Each decision starts with 456.","type":"short_answer"},{"explanation":"A midpoint has equal distances to both endpoints. The upward tie convention chooses an answer consistently, but it does not make one endpoint physically closer.","marking_guide":"Require recognition of equal distances and explicit use of the upward midpoint rule. Merely writing 800 does not show the correction.","question":"A learner says 750 rounds to 800 because 800 is nearer than 700. Correct the reasoning.","sample_answer":"750 is 50 from both 700 and 800, so neither is nearer. It rounds to 800 because we use the agreed upward rule at an exact midpoint.","type":"short_answer"}],"resources":null,"response_prompt":"Type four labelled solutions with endpoints, distances and reasons. For paper work, type a summary and keep the page for your parent. Explain the tie in question 3.","review_status":"unreviewed","seed_key":"s2-mat-y3-w02-l1","sort_activity":null,"source_note":"Official NESA Mathematics K–10 Syllabus (2022) outcomes retrieved on 12 October 2026 confirm MA2-RN-01 and its wording, recorded in lesson-pipeline/sources/nesa-ma2-rn-01.json. Individual lesson alignment and content-point mapping remain pending independent review. The repository catalogue has the conflicting MA2-RWN-01 spelling. This draft claims no verified alignment.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Read the words nearest ten and nearest hundred as choices of scale.","A ten landmark ends in one zero; a hundred landmark ends in two zeros.","Your goal is a justified approximate value while keeping the original count available."],"guided":["Attempt the first practice before reading its comparison feedback.","The first prompt compares gaps to tens; the second asks whether the hundred gaps tie.","Write a distance comparison for the first and a named midpoint convention for the second, then compare your reasons with the feedback."],"learn":["For the complete model, label one line tens and the other hundreds.","In the first model, the tens gap is a single ten, while the hundreds gap spans one hundred.","Follow each subtraction back to its own endpoints and read the reason attached to the chosen value."],"quiz":["Decide whether each question concerns a scale, a distance or a midpoint convention.","Discard options using the wrong kind of landmark before comparing the remaining gaps.","Use the original value for each decision and distinguish equal distances from an endpoint actually being nearer."],"submit":["Make sure your saved work includes reasoning as well as rounded values.","Confirm that the four independent solutions and two written quiz responses have place labels and evidence.","If you used paper, keep the number lines and type a brief account of your comparisons so a parent can review both."],"teach0":["Start by listing consecutive multiples of ten around the number.","Move one ten forwards from the lower landmark, not two tens.","Test that the original number is between your two landmarks and that they are exactly ten apart."],"teach1":["Nearer is about the length of a gap, not the smaller endpoint value.","Subtract the lower ten from the original number, then subtract the original number from the upper ten.","The two gaps should add to ten. Choose the endpoint with the shorter gap after comparing them."],"teach2":["An exact midpoint is equally distant from its neighbouring hundreds.","Compare the two gaps before deciding whether this is a nearest-endpoint problem or a tie.","For equal gaps, name our upward convention rather than saying one landmark is closer."],"teach3":["Identify the requested place before selecting the pair of landmarks.","Use one pair ten apart and another pair one hundred apart, each surrounding the starting value.","Make both comparisons from the original number; do not pass the ten answer into the hundred calculation."],"write":["Label the requested place beside each independent prompt before drawing.","For each line show the original value, the neighbouring landmarks and both gap lengths.","For a shorter gap justify the nearer endpoint; for equal gaps name the tie rule. In the last prompt construct two separate scales."]},"subject":"Number and Algebra","success_criteria":["I can name the two neighbouring tens or hundreds.","I can compare the distances to both endpoints.","I can round a midpoint upwards using the agreed rule.","I can explain why the rounding place changes my answer."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":1,"explanation":"240 and 250 are consecutive multiples of ten. The number 247 lies between them; the other intervals use the wrong scale or miss a neighbouring ten.","options":["200 and 300","240 and 250","230 and 250","247 and 257"],"question":"Which neighbouring tens surround 247?"},"example":"WATCH MY THINKING\nFor 224, I choose 220 and 230 as my endpoints. I count four units back to 220 and six units forward to 230. Four is the shorter distance, so 224 rounds to 220. The actual number remains 224.\n\nYOUR SMALL TRY\nWhich two neighbouring tens surround 237? Write both before comparing with the suggestion.\n\nCOMPARE AFTER TRYING\n230 and 240 are consecutive multiples of ten and 237 is between them. 220 and 240 would span two tens, so they are not neighbours.","explain":"Rounding to the nearest ten means choosing the closest multiple of ten.\n\nA rounded number is a useful approximate value, not a new exact count.\n\nMultiples of ten end in zero: 210, 220, 230. Locate your number between two neighbours. For 224, these are 220 and 230. The word nearest asks which endpoint has the shorter distance. We are not always making a number bigger. We are making it close to a useful landmark. When someone needs an exact count, keep the original number instead of replacing it with the rounded value.","icon":"🔎","notice":"A common mistake is choosing any two numbers ending in zero, such as 200 and 230. Use consecutive multiples with only one ten between them, and make sure the original number sits between them.","title":"Find the neighbouring tens","visual":[{"alt":"224 is four units from 220 and six units from 230, on an equally spaced line with midpoint 225.","caption":"224 lies between 220 and 230. The midpoint is 225.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 150\"><rect width=\"480\" height=\"150\" fill=\"#fff\"/><line x1=\"40\" y1=\"70\" x2=\"440\" y2=\"70\" stroke=\"#1f3b2d\" stroke-width=\"3\"/><line x1=\"40\" y1=\"65\" x2=\"40\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"40\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">220</text><line x1=\"240\" y1=\"65\" x2=\"240\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"240\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">225</text><line x1=\"440\" y1=\"65\" x2=\"440\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"440\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">230</text><circle cx=\"200\" cy=\"70\" r=\"6\" fill=\"#a33321\"/><text x=\"200\" y=\"40\" text-anchor=\"middle\" font-size=\"18\">224</text><text x=\"240\" y=\"135\" text-anchor=\"middle\" font-size=\"16\">Equal spacing shows distance</text></svg>"}]},{"check":{"correct_index":3,"explanation":"The distance to 380 is only 1, while the distance to 390 is 9. The smaller distance makes 380 the nearest multiple of ten.","options":["390","400","381","380"],"question":"381 is 1 from 380 and 9 from 390. What is its nearest ten?"},"example":"WATCH MY THINKING\nFor 368, the endpoints are 360 and 370. The distances are 368 minus 360 = 8, and 370 minus 368 = 2. Since 2 is smaller than 8, I round to 370. The distances add to 10, which confirms I used neighbouring tens.\n\nYOUR SMALL TRY\nRound 432 to the nearest ten using both distances. Make your choice before reading on.\n\nCOMPARE AFTER TRYING\n432 is 2 from 430 and 8 from 440. It rounds to 430 because the lower endpoint is closer, not just because it is lower.","explain":"The nearest endpoint is the one with the smaller distance from the starting number.\n\nCounting both distances explains the choice instead of relying on a guessed direction.\n\nSubtract the lower endpoint from the number to find one distance. Subtract the number from the upper endpoint for the other. The two distances add to ten because there are ten units between the neighbouring tens. A number left of the midpoint is closer to the lower endpoint; a number right of it is closer to the upper one. Do not compare how large the endpoints are. Compare how far away each is.","icon":"🔎","notice":"A common mistake is choosing the lower endpoint simply because its value is smaller. Compare the two distances, not the sizes of the endpoints themselves.","title":"Compare distances to both tens","visual":[{"alt":"368 lies eight units after 360 and two units before 370; the midpoint is 365.","caption":"368 lies between 360 and 370. The midpoint is 365.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 150\"><rect width=\"480\" height=\"150\" fill=\"#fff\"/><line x1=\"40\" y1=\"70\" x2=\"440\" y2=\"70\" stroke=\"#1f3b2d\" stroke-width=\"3\"/><line x1=\"40\" y1=\"65\" x2=\"40\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"40\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">360</text><line x1=\"240\" y1=\"65\" x2=\"240\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"240\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">365</text><line x1=\"440\" y1=\"65\" x2=\"440\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"440\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">370</text><circle cx=\"360\" cy=\"70\" r=\"6\" fill=\"#a33321\"/><text x=\"360\" y=\"40\" text-anchor=\"middle\" font-size=\"18\">368</text><text x=\"240\" y=\"135\" text-anchor=\"middle\" font-size=\"16\">Equal spacing shows distance</text></svg>"}]},{"check":{"correct_index":2,"explanation":"350 is 50 away from both 300 and 400. Equal distances create a tie, and the agreed upward rounding rule selects 400.","options":["350 is closer to 400 than 300.","350 has no rounding answer.","Both distances are equal, so the upward tie rule selects 400.","The first digit always stays unchanged."],"question":"Which reason correctly rounds 350 to the nearest hundred?"},"example":"WATCH MY THINKING\nFor 450, I find 400 and 500. I calculate 450 minus 400 = 50 and 500 minus 450 = 50. I name the tie, then use our upward midpoint rule to round to 500.\n\nYOUR SMALL TRY\nRound 550 to the nearest hundred. Is either endpoint actually nearer?\n\nCOMPARE AFTER TRYING\n550 is 50 from both 500 and 600. It rounds to 600 by the midpoint rule; neither endpoint has a shorter distance.","explain":"For the nearest hundred, use neighbouring multiples of one hundred; at an exact midpoint we round upwards.\n\nThe midpoint rule gives everyone the same answer when both endpoints are equally near.\n\nHundred landmarks end in two zeros. There are one hundred units between neighbours, so their midpoint is fifty units from either end. For 450 the endpoints are 400 and 500, not 440 and 460. Both distances are 50. Neither endpoint is nearer, so we use the agreed upward rounding rule. This is a convention for a tie, not proof that the upper endpoint is closer. Below the midpoint choose the lower hundred, and above it choose the upper hundred.","icon":"🔎","notice":"A common mistake is saying the upper endpoint is nearer at the midpoint. State that the distances are equal, then name the upward rounding convention.","title":"Use hundreds and recognise a tie","visual":[{"alt":"450 is exactly fifty units from both 400 and 500, at the midpoint of the hundred interval.","caption":"450 lies between 400 and 500. The midpoint is 450.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 150\"><rect width=\"480\" height=\"150\" fill=\"#fff\"/><line x1=\"40\" y1=\"70\" x2=\"440\" y2=\"70\" stroke=\"#1f3b2d\" stroke-width=\"3\"/><line x1=\"40\" y1=\"65\" x2=\"40\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"40\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">400</text><line x1=\"240\" y1=\"65\" x2=\"240\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"240\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">450</text><line x1=\"440\" y1=\"65\" x2=\"440\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"440\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">500</text><circle cx=\"240\" cy=\"70\" r=\"6\" fill=\"#a33321\"/><text x=\"240\" y=\"40\" text-anchor=\"middle\" font-size=\"18\">450</text><text x=\"240\" y=\"135\" text-anchor=\"middle\" font-size=\"16\">Equal spacing shows distance</text></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I have 450 on a line from 400 to 500. Is 500 closer?","who":"pip"},{"text":"Calculate both distances. Each is fifty, so neither endpoint is closer.","who":"juno"},{"text":"Then I name the tie and use our agreed upward midpoint rule.","who":"pip"},{"pause_after":true,"text":"Pause and explain why a midpoint rule is different from choosing a shorter distance.","who":"juno"}]}],"title":"What happens at the midpoint?","transcript":"Pip: I have 450 on a line from 400 to 500. Is 500 closer?\nJuno: Calculate both distances. Each is fifty, so neither endpoint is closer.\nPip: Then I name the tie and use our agreed upward midpoint rule.\nJuno: Pause and explain why a midpoint rule is different from choosing a shorter distance."}}]},{"check":{"correct_index":0,"explanation":"674 is 4 from 670 and 6 from 680, so its nearest ten is 670. It is 26 from 700 and 74 from 600, so its nearest hundred is 700.","options":["670 and 700","680 and 700","670 and 600","674 and 700"],"question":"Which pair directly rounds 674 to the nearest ten and then separately to the nearest hundred?"},"example":"WATCH MY THINKING\nI round 726 directly to a ten: 730 is 4 away, closer than 720 at 6 away. I start again with the original 726 for a hundred: 700 is 26 away, closer than 800 at 74 away. My two answers use different scales.\n\nYOUR SMALL TRY\nRound 584 directly to the nearest ten and directly to the nearest hundred. Record each pair of endpoints.\n\nCOMPARE AFTER TRYING\nFor tens, 580 and 590 give distances 4 and 6, so choose 580. For hundreds, 500 and 600 give distances 84 and 16, so choose 600. Both decisions start with 584.","explain":"The requested place determines the landmarks: tens are ten apart and hundreds are one hundred apart.\n\nThe same starting number can have different rounded values because the useful scale has changed.\n\nRead the instruction before drawing your line. For 726 to the nearest ten, use 720 and 730; its distances are 6 and 4. For the nearest hundred, use 700 and 800; its distances are 26 and 74. Both answers are reasonable approximations for different purposes. Write the original number, the rounding place and your chosen value so a reader knows what you did. Do not round to tens first and then to hundreds; make each decision directly from the original number.","icon":"🔎","notice":"A common mistake is rounding to a ten first and then rounding that result to a hundred. Return to the original number for each place. For 449, direct hundred rounding gives 400; rounding through 450 would give the wrong hundred.","title":"Choose the scale before calculating","visual":[{"alt":"726 is twenty-six units from 700 and seventy-four units from 800; the hundred midpoint is 750.","caption":"726 lies between 700 and 800. The midpoint is 750.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 150\"><rect width=\"480\" height=\"150\" fill=\"#fff\"/><line x1=\"40\" y1=\"70\" x2=\"440\" y2=\"70\" stroke=\"#1f3b2d\" stroke-width=\"3\"/><line x1=\"40\" y1=\"65\" x2=\"40\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"40\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">700</text><line x1=\"240\" y1=\"65\" x2=\"240\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"240\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">750</text><line x1=\"440\" y1=\"65\" x2=\"440\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"440\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">800</text><circle cx=\"144\" cy=\"70\" r=\"6\" fill=\"#a33321\"/><text x=\"144\" y=\"40\" text-anchor=\"middle\" font-size=\"18\">726</text><text x=\"240\" y=\"135\" text-anchor=\"middle\" font-size=\"16\">Equal spacing shows distance</text></svg>"}]}],"title":"Rounding numbers: which landmark is nearer?","unit_number":1,"unit_title":"Whole numbers and place value","week":2,"week_in_unit":2,"word_challenges":null,"worked_example":"I DO: Round 286 to the nearest ten, and separately to the nearest hundred.\nTens: 280 and 290 bracket 286. Distances are 6 and 4; choose 290.\nHundreds: 200 and 300 bracket the original 286. Distances are 86 and 14; choose 300.\nI label the rounding place beside each answer. Neither calculation changes the exact starting number.\nFor a tie example, round 735 to a ten: 730 and 740 are each 5 away. The upward rule selects 740.","worked_visuals":[{"alt":"224 is four units from 220 and six units from 230, on an equally spaced line with midpoint 225.","caption":"224 lies between 220 and 230. The midpoint is 225.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 150\"><rect width=\"480\" height=\"150\" fill=\"#fff\"/><line x1=\"40\" y1=\"70\" x2=\"440\" y2=\"70\" stroke=\"#1f3b2d\" stroke-width=\"3\"/><line x1=\"40\" y1=\"65\" x2=\"40\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"40\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">220</text><line x1=\"240\" y1=\"65\" x2=\"240\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"240\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">225</text><line x1=\"440\" y1=\"65\" x2=\"440\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"440\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">230</text><circle cx=\"200\" cy=\"70\" r=\"6\" fill=\"#a33321\"/><text x=\"200\" y=\"40\" text-anchor=\"middle\" font-size=\"18\">224</text><text x=\"240\" y=\"135\" text-anchor=\"middle\" font-size=\"16\">Equal spacing shows distance</text></svg>"},{"alt":"450 is exactly fifty units from both 400 and 500, at the midpoint of the hundred interval.","caption":"450 lies between 400 and 500. The midpoint is 450.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 150\"><rect width=\"480\" height=\"150\" fill=\"#fff\"/><line x1=\"40\" y1=\"70\" x2=\"440\" y2=\"70\" stroke=\"#1f3b2d\" stroke-width=\"3\"/><line x1=\"40\" y1=\"65\" x2=\"40\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"40\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">400</text><line x1=\"240\" y1=\"65\" x2=\"240\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"240\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">450</text><line x1=\"440\" y1=\"65\" x2=\"440\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"440\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">500</text><circle cx=\"240\" cy=\"70\" r=\"6\" fill=\"#a33321\"/><text x=\"240\" y=\"40\" text-anchor=\"middle\" font-size=\"18\">450</text><text x=\"240\" y=\"135\" text-anchor=\"middle\" font-size=\"16\">Equal spacing shows distance</text></svg>"},{"alt":"726 is twenty-six units from 700 and seventy-four units from 800; the hundred midpoint is 750.","caption":"726 lies between 700 and 800. The midpoint is 750.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 150\"><rect width=\"480\" height=\"150\" fill=\"#fff\"/><line x1=\"40\" y1=\"70\" x2=\"440\" y2=\"70\" stroke=\"#1f3b2d\" stroke-width=\"3\"/><line x1=\"40\" y1=\"65\" x2=\"40\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"40\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">700</text><line x1=\"240\" y1=\"65\" x2=\"240\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"240\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">750</text><line x1=\"440\" y1=\"65\" x2=\"440\" y2=\"80\" stroke=\"#1f3b2d\"/><text x=\"440\" y=\"103\" text-anchor=\"middle\" font-size=\"16\">800</text><circle cx=\"144\" cy=\"70\" r=\"6\" fill=\"#a33321\"/><text x=\"144\" y=\"40\" text-anchor=\"middle\" font-size=\"18\">726</text><text x=\"240\" y=\"135\" text-anchor=\"middle\" font-size=\"16\">Equal spacing shows distance</text></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-mat-y3-w02-l1' AND family_id IS NULL;
